CREATE TABLE public.caixa_sessoes (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), clinica_id uuid NOT NULL REFERENCES public.clinicas(id), unidade_id uuid NOT NULL REFERENCES public.unidades(id), conta_financeira_id uuid NOT NULL REFERENCES public.contas_financeiras(id), operador_id uuid NOT NULL DEFAULT auth.uid(), aberto_em timestamptz NOT NULL DEFAULT now(), saldo_inicial numeric(12,2) NOT NULL DEFAULT 0, fechado_em timestamptz, saldo_informado numeric(12,2), saldo_calculado numeric(12,2), diferenca numeric(12,2), conferencia jsonb NOT NULL DEFAULT '{}'::jsonb, justificativa text, status text NOT NULL DEFAULT 'aberto' CHECK(status IN ('aberto','fechado')));
GRANT SELECT ON public.caixa_sessoes TO authenticated; GRANT ALL ON public.caixa_sessoes TO service_role; ALTER TABLE public.caixa_sessoes ENABLE ROW LEVEL SECURITY;
CREATE UNIQUE INDEX caixa_sessao_aberta_operador ON public.caixa_sessoes(clinica_id,unidade_id,operador_id) WHERE status='aberto';
CREATE POLICY "caixa_select" ON public.caixa_sessoes FOR SELECT TO authenticated USING(clinica_id=current_clinica_id() AND (tem_papel('owner','admin','financeiro') OR (tem_papel('recepcao') AND operador_id=auth.uid())));
CREATE TRIGGER trg_auditar AFTER INSERT OR UPDATE OR DELETE ON public.caixa_sessoes FOR EACH ROW EXECUTE FUNCTION public.auditar();

CREATE TABLE public.caixa_movimentos (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), clinica_id uuid NOT NULL REFERENCES public.clinicas(id), unidade_id uuid NOT NULL REFERENCES public.unidades(id), sessao_id uuid NOT NULL REFERENCES public.caixa_sessoes(id), tipo text NOT NULL CHECK(tipo IN ('suprimento','sangria')), valor numeric(12,2) NOT NULL CHECK(valor>0), motivo text NOT NULL CHECK(length(trim(motivo))>=3), created_by uuid NOT NULL DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.caixa_movimentos TO authenticated; GRANT ALL ON public.caixa_movimentos TO service_role; ALTER TABLE public.caixa_movimentos ENABLE ROW LEVEL SECURITY;
CREATE POLICY "caixa_mov_select" ON public.caixa_movimentos FOR SELECT TO authenticated USING(clinica_id=current_clinica_id() AND (tem_papel('owner','admin','financeiro') OR (tem_papel('recepcao') AND created_by=auth.uid())));
CREATE TRIGGER trg_auditar AFTER INSERT OR UPDATE OR DELETE ON public.caixa_movimentos FOR EACH ROW EXECUTE FUNCTION public.auditar();

CREATE TABLE public.financeiro_baixas (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), clinica_id uuid NOT NULL REFERENCES public.clinicas(id), unidade_id uuid REFERENCES public.unidades(id), recebimento_id uuid REFERENCES public.financeiro_recebimentos(id), pagamento_id uuid REFERENCES public.financeiro_pagamentos(id), conta_financeira_id uuid NOT NULL REFERENCES public.contas_financeiras(id), forma_pagamento_id uuid REFERENCES public.formas_pagamento(id), valor numeric(12,2) NOT NULL CHECK(valor>0), juros numeric(12,2) NOT NULL DEFAULT 0 CHECK(juros>=0), multa numeric(12,2) NOT NULL DEFAULT 0 CHECK(multa>=0), desconto numeric(12,2) NOT NULL DEFAULT 0 CHECK(desconto>=0), tipo text NOT NULL DEFAULT 'baixa' CHECK(tipo IN ('baixa','estorno')), motivo text, pago_em date NOT NULL DEFAULT current_date, caixa_sessao_id uuid REFERENCES public.caixa_sessoes(id), created_by uuid DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), CHECK((recebimento_id IS NOT NULL)::integer+(pagamento_id IS NOT NULL)::integer=1), CHECK(tipo='baixa' OR length(trim(coalesce(motivo,'')))>=5));
GRANT SELECT ON public.financeiro_baixas TO authenticated; GRANT ALL ON public.financeiro_baixas TO service_role; ALTER TABLE public.financeiro_baixas ENABLE ROW LEVEL SECURITY;
CREATE POLICY "baixas_select_fin" ON public.financeiro_baixas FOR SELECT TO authenticated USING(clinica_id=current_clinica_id() AND tem_papel('owner','admin','financeiro'));
CREATE POLICY "baixas_select_recepcao" ON public.financeiro_baixas FOR SELECT TO authenticated USING(clinica_id=current_clinica_id() AND tem_papel('recepcao') AND recebimento_id IS NOT NULL AND pago_em=current_date);
CREATE TRIGGER trg_auditar AFTER INSERT OR UPDATE OR DELETE ON public.financeiro_baixas FOR EACH ROW EXECUTE FUNCTION public.auditar();
CREATE INDEX financeiro_baixas_data_idx ON public.financeiro_baixas(clinica_id,pago_em);

CREATE TABLE public.financeiro_recorrencias (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), clinica_id uuid NOT NULL REFERENCES public.clinicas(id), unidade_id uuid REFERENCES public.unidades(id), tipo text NOT NULL CHECK(tipo IN ('receber','pagar')), descricao text NOT NULL, valor numeric(12,2) NOT NULL CHECK(valor>0), dia_vencimento integer NOT NULL CHECK(dia_vencimento BETWEEN 1 AND 31), inicio date NOT NULL, fim date, conta_id uuid REFERENCES public.plano_contas(id), conta_financeira_id uuid REFERENCES public.contas_financeiras(id), centro_custo_id uuid REFERENCES public.centros_custo(id), forma_pagamento_id uuid REFERENCES public.formas_pagamento(id), ativo boolean NOT NULL DEFAULT true, ultimo_mes_gerado date, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.financeiro_recorrencias TO authenticated; GRANT ALL ON public.financeiro_recorrencias TO service_role; ALTER TABLE public.financeiro_recorrencias ENABLE ROW LEVEL SECURITY;
CREATE POLICY "recorrencias_select" ON public.financeiro_recorrencias FOR SELECT TO authenticated USING(clinica_id=current_clinica_id() AND tem_papel('owner','admin','financeiro'));
CREATE POLICY "recorrencias_write" ON public.financeiro_recorrencias FOR ALL TO authenticated USING(clinica_id=current_clinica_id() AND tem_papel('owner','admin','financeiro')) WITH CHECK(clinica_id=current_clinica_id() AND tem_papel('owner','admin','financeiro'));
CREATE TRIGGER trg_auditar AFTER INSERT OR UPDATE OR DELETE ON public.financeiro_recorrencias FOR EACH ROW EXECUTE FUNCTION public.auditar();

CREATE OR REPLACE FUNCTION public.bloquear_registro_financeiro_imutavel() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN RAISE EXCEPTION 'Registro financeiro confirmado é imutável; faça um estorno com motivo'; END $$;
CREATE TRIGGER trg_baixa_imutavel BEFORE UPDATE OR DELETE ON public.financeiro_baixas FOR EACH ROW EXECUTE FUNCTION public.bloquear_registro_financeiro_imutavel();
CREATE TRIGGER trg_caixa_mov_imutavel BEFORE UPDATE OR DELETE ON public.caixa_movimentos FOR EACH ROW EXECUTE FUNCTION public.bloquear_registro_financeiro_imutavel();

CREATE OR REPLACE FUNCTION public.atualizar_totais_lancamento(p_tipo text,p_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_total numeric(12,2); v_pago numeric(12,2); v_data date;
BEGIN
 IF p_tipo='receber' THEN
  SELECT valor,vencimento INTO v_total,v_data FROM financeiro_recebimentos WHERE id=p_id;
  SELECT coalesce(sum(CASE WHEN tipo='baixa' THEN valor+juros+multa-desconto ELSE -(valor+juros+multa-desconto) END),0)::numeric(12,2) INTO v_pago FROM financeiro_baixas WHERE recebimento_id=p_id;
  UPDATE financeiro_recebimentos SET valor_pago=greatest(v_pago,0),pago_em=CASE WHEN v_pago>=v_total THEN current_date ELSE NULL END,status=CASE WHEN v_pago>=v_total THEN 'pago'::lancamento_status WHEN v_data<current_date THEN 'atrasado'::lancamento_status ELSE 'pendente'::lancamento_status END WHERE id=p_id AND status<>'cancelado';
 ELSE
  SELECT valor,vencimento INTO v_total,v_data FROM financeiro_pagamentos WHERE id=p_id;
  SELECT coalesce(sum(CASE WHEN tipo='baixa' THEN valor+juros+multa-desconto ELSE -(valor+juros+multa-desconto) END),0)::numeric(12,2) INTO v_pago FROM financeiro_baixas WHERE pagamento_id=p_id;
  UPDATE financeiro_pagamentos SET valor_pago=greatest(v_pago,0),pago_em=CASE WHEN v_pago>=v_total THEN current_date ELSE NULL END,status=CASE WHEN v_pago>=v_total THEN 'pago'::lancamento_status WHEN v_data<current_date THEN 'atrasado'::lancamento_status ELSE 'pendente'::lancamento_status END WHERE id=p_id AND status<>'cancelado';
 END IF;
END $$;

CREATE OR REPLACE FUNCTION public.registrar_baixa(p_tipo text,p_lancamento uuid,p_valor numeric,p_conta uuid,p_forma uuid DEFAULT NULL,p_data date DEFAULT current_date,p_juros numeric DEFAULT 0,p_multa numeric DEFAULT 0,p_desconto numeric DEFAULT 0,p_caixa uuid DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_clinica uuid;v_unidade uuid;v_status lancamento_status;v_total numeric(12,2);v_pago numeric(12,2);v_id uuid;
BEGIN
 IF NOT (tem_papel('owner','admin','financeiro') OR (p_tipo='receber' AND tem_papel('recepcao') AND coalesce(p_data,current_date)=current_date AND p_caixa IS NOT NULL)) THEN RAISE EXCEPTION 'Sem permissão para registrar esta baixa'; END IF;
 IF p_tipo='receber' THEN SELECT clinica_id,unidade_id,status,valor,valor_pago INTO v_clinica,v_unidade,v_status,v_total,v_pago FROM financeiro_recebimentos WHERE id=p_lancamento FOR UPDATE;
 ELSIF p_tipo='pagar' THEN SELECT clinica_id,unidade_id,status,valor,valor_pago INTO v_clinica,v_unidade,v_status,v_total,v_pago FROM financeiro_pagamentos WHERE id=p_lancamento FOR UPDATE; ELSE RAISE EXCEPTION 'Tipo inválido'; END IF;
 IF v_clinica IS NULL OR v_clinica<>current_clinica_id() THEN RAISE EXCEPTION 'Lançamento não encontrado'; END IF;
 IF v_status='cancelado' OR v_pago>=v_total THEN RAISE EXCEPTION 'Lançamento não está em aberto'; END IF;
 IF round(coalesce(p_valor,0),2)<=0 OR round(p_valor,2)>round(v_total-v_pago,2) THEN RAISE EXCEPTION 'Valor da baixa inválido'; END IF;
 IF NOT EXISTS(SELECT 1 FROM contas_financeiras WHERE id=p_conta AND clinica_id=v_clinica AND ativo) THEN RAISE EXCEPTION 'Conta financeira inválida'; END IF;
 IF p_caixa IS NOT NULL AND NOT EXISTS(SELECT 1 FROM caixa_sessoes WHERE id=p_caixa AND clinica_id=v_clinica AND status='aberto' AND (operador_id=auth.uid() OR tem_papel('owner','admin','financeiro'))) THEN RAISE EXCEPTION 'Caixa não está aberto'; END IF;
 INSERT INTO financeiro_baixas(clinica_id,unidade_id,recebimento_id,pagamento_id,conta_financeira_id,forma_pagamento_id,valor,juros,multa,desconto,pago_em,caixa_sessao_id) VALUES(v_clinica,v_unidade,CASE WHEN p_tipo='receber' THEN p_lancamento END,CASE WHEN p_tipo='pagar' THEN p_lancamento END,p_conta,p_forma,round(p_valor,2),round(coalesce(p_juros,0),2),round(coalesce(p_multa,0),2),round(coalesce(p_desconto,0),2),coalesce(p_data,current_date),p_caixa) RETURNING id INTO v_id;
 PERFORM atualizar_totais_lancamento(p_tipo,p_lancamento); RETURN v_id;
END $$;

CREATE OR REPLACE FUNCTION public.estornar_baixa(p_baixa uuid,p_motivo text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE b financeiro_baixas%ROWTYPE;v_id uuid;
BEGIN
 IF NOT tem_papel('owner','admin','financeiro') THEN RAISE EXCEPTION 'Sem permissão para estornar'; END IF; IF length(trim(coalesce(p_motivo,'')))<5 THEN RAISE EXCEPTION 'Informe o motivo do estorno'; END IF;
 SELECT * INTO b FROM financeiro_baixas WHERE id=p_baixa FOR UPDATE; IF NOT FOUND OR b.clinica_id<>current_clinica_id() OR b.tipo<>'baixa' THEN RAISE EXCEPTION 'Baixa não encontrada'; END IF;
 IF EXISTS(SELECT 1 FROM financeiro_baixas WHERE tipo='estorno' AND motivo LIKE '%'||b.id::text||'%') THEN RAISE EXCEPTION 'Baixa já estornada'; END IF;
 INSERT INTO financeiro_baixas(clinica_id,unidade_id,recebimento_id,pagamento_id,conta_financeira_id,forma_pagamento_id,valor,juros,multa,desconto,tipo,motivo,pago_em) VALUES(b.clinica_id,b.unidade_id,b.recebimento_id,b.pagamento_id,b.conta_financeira_id,b.forma_pagamento_id,b.valor,b.juros,b.multa,b.desconto,'estorno','Estorno de '||b.id::text||': '||trim(p_motivo),current_date) RETURNING id INTO v_id;
 PERFORM atualizar_totais_lancamento(CASE WHEN b.recebimento_id IS NOT NULL THEN 'receber' ELSE 'pagar' END,coalesce(b.recebimento_id,b.pagamento_id)); RETURN v_id;
END $$;

CREATE OR REPLACE FUNCTION public.abrir_caixa(p_unidade uuid,p_conta uuid,p_saldo_inicial numeric) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_id uuid;v_clinica uuid:=current_clinica_id(); BEGIN IF NOT tem_papel('owner','admin','financeiro','recepcao') THEN RAISE EXCEPTION 'Sem permissão para abrir caixa'; END IF; IF NOT EXISTS(SELECT 1 FROM unidades WHERE id=p_unidade AND clinica_id=v_clinica) OR NOT EXISTS(SELECT 1 FROM contas_financeiras WHERE id=p_conta AND clinica_id=v_clinica AND tipo='caixa' AND ativo) THEN RAISE EXCEPTION 'Unidade ou conta de caixa inválida'; END IF; INSERT INTO caixa_sessoes(clinica_id,unidade_id,conta_financeira_id,saldo_inicial) VALUES(v_clinica,p_unidade,p_conta,round(coalesce(p_saldo_inicial,0),2)) RETURNING id INTO v_id;RETURN v_id;END $$;
CREATE OR REPLACE FUNCTION public.movimentar_caixa(p_sessao uuid,p_tipo text,p_valor numeric,p_motivo text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s caixa_sessoes%ROWTYPE;v_id uuid;BEGIN SELECT * INTO s FROM caixa_sessoes WHERE id=p_sessao FOR UPDATE;IF NOT FOUND OR s.clinica_id<>current_clinica_id() OR s.status<>'aberto' THEN RAISE EXCEPTION 'Caixa não está aberto';END IF;IF NOT (tem_papel('owner','admin','financeiro') OR (tem_papel('recepcao') AND s.operador_id=auth.uid())) THEN RAISE EXCEPTION 'Sem permissão';END IF;INSERT INTO caixa_movimentos(clinica_id,unidade_id,sessao_id,tipo,valor,motivo) VALUES(s.clinica_id,s.unidade_id,s.id,p_tipo,round(p_valor,2),trim(p_motivo)) RETURNING id INTO v_id;RETURN v_id;END $$;
CREATE OR REPLACE FUNCTION public.fechar_caixa(p_sessao uuid,p_saldo_informado numeric,p_conferencia jsonb,p_justificativa text DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s caixa_sessoes%ROWTYPE;v_calc numeric(12,2);v_dif numeric(12,2);BEGIN SELECT * INTO s FROM caixa_sessoes WHERE id=p_sessao FOR UPDATE;IF NOT FOUND OR s.clinica_id<>current_clinica_id() OR s.status<>'aberto' THEN RAISE EXCEPTION 'Caixa não está aberto';END IF;IF NOT (tem_papel('owner','admin','financeiro') OR (tem_papel('recepcao') AND s.operador_id=auth.uid())) THEN RAISE EXCEPTION 'Sem permissão';END IF;SELECT s.saldo_inicial+coalesce((SELECT sum(CASE WHEN tipo='suprimento' THEN valor ELSE -valor END) FROM caixa_movimentos WHERE sessao_id=s.id),0)+coalesce((SELECT sum(CASE WHEN b.tipo='baixa' THEN b.valor+b.juros+b.multa-b.desconto ELSE -(b.valor+b.juros+b.multa-b.desconto) END) FROM financeiro_baixas b WHERE b.caixa_sessao_id=s.id AND b.recebimento_id IS NOT NULL),0) INTO v_calc;v_dif:=round(coalesce(p_saldo_informado,0)-v_calc,2);IF v_dif<>0 AND length(trim(coalesce(p_justificativa,'')))<5 THEN RAISE EXCEPTION 'Informe a justificativa da diferença';END IF;UPDATE caixa_sessoes SET fechado_em=now(),saldo_informado=round(p_saldo_informado,2),saldo_calculado=v_calc,diferenca=v_dif,conferencia=coalesce(p_conferencia,'{}'),justificativa=nullif(trim(p_justificativa),''),status='fechado' WHERE id=s.id;END $$;

CREATE OR REPLACE FUNCTION public.atualizar_lancamentos_atrasados() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_rec integer;v_pag integer;BEGIN UPDATE financeiro_recebimentos SET status='atrasado' WHERE status='pendente' AND vencimento<current_date AND valor_pago<valor;GET DIAGNOSTICS v_rec=ROW_COUNT;UPDATE financeiro_pagamentos SET status='atrasado' WHERE status='pendente' AND vencimento<current_date AND valor_pago<valor;GET DIAGNOSTICS v_pag=ROW_COUNT;RETURN v_rec+v_pag;END $$;
CREATE OR REPLACE FUNCTION public.gerar_recorrencias_financeiras(p_mes date DEFAULT current_date) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r record;v_mes date:=date_trunc('month',p_mes)::date;v_venc date;v_n integer:=0;BEGIN FOR r IN SELECT * FROM financeiro_recorrencias WHERE ativo AND inicio<=v_mes+interval '1 month - 1 day' AND (fim IS NULL OR fim>=v_mes) AND (ultimo_mes_gerado IS NULL OR ultimo_mes_gerado<v_mes) LOOP v_venc:=v_mes+(least(r.dia_vencimento,extract(day from(v_mes+interval '1 month - 1 day'))::int)-1);IF r.tipo='receber' THEN INSERT INTO financeiro_recebimentos(clinica_id,unidade_id,conta_id,conta_financeira_id,centro_custo_id,forma_pagamento_id,descricao,valor,valor_bruto,valor_liquido,vencimento,competencia,recorrencia_id) VALUES(r.clinica_id,r.unidade_id,r.conta_id,r.conta_financeira_id,r.centro_custo_id,r.forma_pagamento_id,r.descricao,r.valor,r.valor,r.valor,v_venc,v_mes,r.id);ELSE INSERT INTO financeiro_pagamentos(clinica_id,unidade_id,conta_id,conta_financeira_id,centro_custo_id,forma_pagamento_id,descricao,valor,valor_bruto,valor_liquido,vencimento,competencia,recorrencia_id) VALUES(r.clinica_id,r.unidade_id,r.conta_id,r.conta_financeira_id,r.centro_custo_id,r.forma_pagamento_id,r.descricao,r.valor,r.valor,r.valor,v_venc,v_mes,r.id);END IF;UPDATE financeiro_recorrencias SET ultimo_mes_gerado=v_mes WHERE id=r.id;v_n:=v_n+1;END LOOP;RETURN v_n;END $$;

CREATE VIEW public.contas_financeiras_saldos WITH(security_invoker=true) AS SELECT c.*,(c.saldo_inicial+coalesce(sum(CASE WHEN b.tipo='baixa' AND b.recebimento_id IS NOT NULL THEN b.valor+b.juros+b.multa-b.desconto WHEN b.tipo='baixa' AND b.pagamento_id IS NOT NULL THEN -(b.valor+b.juros+b.multa-b.desconto) WHEN b.tipo='estorno' AND b.recebimento_id IS NOT NULL THEN -(b.valor+b.juros+b.multa-b.desconto) ELSE b.valor+b.juros+b.multa-b.desconto END),0))::numeric(12,2) AS saldo FROM contas_financeiras c LEFT JOIN financeiro_baixas b ON b.conta_financeira_id=c.id GROUP BY c.id;
GRANT SELECT ON public.contas_financeiras_saldos TO authenticated;

DROP POLICY IF EXISTS "fin select" ON public.financeiro_recebimentos;DROP POLICY IF EXISTS "fin insert" ON public.financeiro_recebimentos;DROP POLICY IF EXISTS "fin update" ON public.financeiro_recebimentos;DROP POLICY IF EXISTS "fin delete nao pago" ON public.financeiro_recebimentos;DROP POLICY IF EXISTS "fin select" ON public.financeiro_pagamentos;DROP POLICY IF EXISTS "fin insert" ON public.financeiro_pagamentos;DROP POLICY IF EXISTS "fin update" ON public.financeiro_pagamentos;DROP POLICY IF EXISTS "fin delete nao pago" ON public.financeiro_pagamentos;
CREATE POLICY "recebimentos_select_fin" ON public.financeiro_recebimentos FOR SELECT TO authenticated USING(clinica_id=current_clinica_id() AND tem_papel('owner','admin','financeiro'));CREATE POLICY "recebimentos_select_recepcao" ON public.financeiro_recebimentos FOR SELECT TO authenticated USING(clinica_id=current_clinica_id() AND tem_papel('recepcao') AND (vencimento=current_date OR pago_em=current_date));CREATE POLICY "recebimentos_insert_fin" ON public.financeiro_recebimentos FOR INSERT TO authenticated WITH CHECK(clinica_id=current_clinica_id() AND tem_papel('owner','admin','financeiro'));CREATE POLICY "recebimentos_update_fin" ON public.financeiro_recebimentos FOR UPDATE TO authenticated USING(clinica_id=current_clinica_id() AND tem_papel('owner','admin','financeiro')) WITH CHECK(clinica_id=current_clinica_id());CREATE POLICY "pagamentos_select_fin" ON public.financeiro_pagamentos FOR SELECT TO authenticated USING(clinica_id=current_clinica_id() AND tem_papel('owner','admin','financeiro'));CREATE POLICY "pagamentos_insert_fin" ON public.financeiro_pagamentos FOR INSERT TO authenticated WITH CHECK(clinica_id=current_clinica_id() AND tem_papel('owner','admin','financeiro'));CREATE POLICY "pagamentos_update_fin" ON public.financeiro_pagamentos FOR UPDATE TO authenticated USING(clinica_id=current_clinica_id() AND tem_papel('owner','admin','financeiro')) WITH CHECK(clinica_id=current_clinica_id());
REVOKE INSERT,UPDATE,DELETE ON public.financeiro_baixas,public.caixa_sessoes,public.caixa_movimentos FROM authenticated;REVOKE EXECUTE ON FUNCTION public.atualizar_totais_lancamento(text,uuid),public.atualizar_lancamentos_atrasados(),public.gerar_recorrencias_financeiras(date) FROM PUBLIC,anon,authenticated;REVOKE EXECUTE ON FUNCTION public.registrar_baixa(text,uuid,numeric,uuid,uuid,date,numeric,numeric,numeric,uuid),public.estornar_baixa(uuid,text),public.abrir_caixa(uuid,uuid,numeric),public.movimentar_caixa(uuid,text,numeric,text),public.fechar_caixa(uuid,numeric,jsonb,text) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.registrar_baixa(text,uuid,numeric,uuid,uuid,date,numeric,numeric,numeric,uuid),public.estornar_baixa(uuid,text),public.abrir_caixa(uuid,uuid,numeric),public.movimentar_caixa(uuid,text,numeric,text),public.fechar_caixa(uuid,numeric,jsonb,text) TO authenticated;